{-# LANGUAGE RankNTypes #-}
{-# LANGUAGE NoImplicitPrelude #-}

module Main where
import qualified Prelude as P

newtype CBool = CB { runCB :: forall a. a -> a -> a }
true  = CB (\t _ -> t)
false = CB (\_ f -> f)

newtype ListC a = LC { runLC :: forall r. (a -> r -> r) -> r -> r }
nilC            = LC (\_ z -> z)
consC h t       = LC (\c n -> c h (runLC t c n))

andC (CB p) (CB q) = CB (\t f -> p (q t f) f)
orC  (CB p) (CB q) = CB (\t f -> p t (q t f))
notC (CB b)        = CB (\t f -> b f t)
xorC a b           = orC (andC a (notC b)) (andC (notC a) b)
eqBit a b          = notC (xorC a b)

fromList   = P.foldr consC nilC
toList xs  = runLC xs (\x acc -> x : acc) []
zipWithC f = \xs ys -> fromList (P.zipWith f (toList xs) (toList ys))

eqList :: ListC CBool -> ListC CBool -> CBool
eqList xs ys =
  let xsL = toList xs
      ysL = toList ys
      sameLen = P.length xsL P.== P.length ysL
      sameBits = P.and (P.zipWith (\a b ->
                                     runCB (eqBit a b) P.True P.False)
                                  xsL ysL)
  in if sameLen P.&& sameBits then true else false

