{-# NOINLINE checker #-}
checker :: ListC CBool -> CBool
checker flagBits = eqList (zipWithC xorC flagBits keyBits) targetBits

stringBits :: P.String -> ListC CBool
stringBits = fromList P.. P.concatMap (byteBits P.. P.fromEnum)
byteBits n = [ if ((n `P.div` pow2 k) `P.mod` 2) P.== 1 then true else false
               | k <- [7,6..0] ]
pow2 0 = 1
pow2 n = 2 P.* pow2 (n P.- 1)

main :: P.IO ()
main = do
  s <- P.getLine
  let msg = runCB (checker (stringBits s)) "correct" "wrong"
  P.putStrLn msg
